# Generated by Phase: IMPLEMENT | Feature: EVOL-043
"""Injection budgets: one home (`config/quality.json` → `budgets`), one reader that runs the REAL producer
against its worst-case input and measures what it emits. Not the file size — the bytes a session receives.

  session_start  scripts/validate-governance.sh --banner
  prompt_submit  scripts/governance-onprompt.sh under GOVERNANCE_ONPROMPT_WORST_CASE=1 (reload + stale warning forced)
  pre_edit       .claude/hooks/deliver-governance.sh on the path that matches the most families and classes
  snapshot       .context/governance_snapshot.md (bytes on disk; n/a where no snapshot exists)
  law_sentence_max_chars / dc_invariant_max_chars  shape budgets, checked over the corpus
  claude_md_advisory  the CLAUDE.md in bytes (the template in the framework repo, a project's own file elsewhere) — OPTIONAL and ADVISORY (EVOL-064):
                      over the key is a WARN row that stays ok; no key, no row

  notebook_reinject    EVOL-133: gate.py notebook --hook-json at UserPromptSubmit on a throw-away claimed notebook larger
                       than the key, reload pending — the <session-notebook> block (never counted in prompt_submit)
  notebook_precompact  EVOL-133: scripts/governance-oncompact.sh on a throw-away claimed notebook and a transcript with
                       every author delivered after it — the advisory for the summary

  launch_context  EVOL-141: the memory files the harness loads at launch — root CLAUDE.md, .claude/CLAUDE.md, CLAUDE.local.md,
                  their @imports (five hops, outside code, inside the project) and every .claude/rules/**/*.md with no `paths:`
                  that claudeMdExcludes (project + local settings) does not match; the framework repo measures its templates
                  as they land (manifest targets, the settings template's excludes)

  hook_output_cap  the harness cap on one hook's text (#240): every injection key above it is a RED row — over the
                   cap the harness swaps the text for a file path the model never reads

A producer that is absent, exits non-zero, or emits nothing (banner, prompt, pre-edit delivery) is a RED row:
a dead producer is exactly the failure the gate exists to catch. A missing budget key is a red row too.
The caller (gate.py budget) exits 1 on any red row; only an unreadable config/quality.json is exit 2.
"""
from __future__ import annotations

import datetime
import json
import os
import re
import shutil
import subprocess
import tempfile
import uuid
from pathlib import Path

from .common import _glob_regex, GateFault, any_glob, context, frontmatter_of, key
from .corpus import catalog, laws, universe

REQUIRED = ("session_start", "prompt_submit", "pre_edit", "snapshot", "law_sentence_max_chars", "dc_invariant_max_chars", "hook_output_cap",
            "notebook_reinject", "notebook_precompact", "launch_context")
MUST_EMIT = ("session_start", "prompt_submit", "pre_edit", "notebook_reinject", "notebook_precompact")   # an empty emission from these is a dead producer, never "within budget"


class ProducerFault(GateFault):
    """A producer exited non-zero or is absent: a RED row (verdict), not an infrastructure fault."""


def _run(repo: Path, cmd: list[str], stdin: str = "", env: dict | None = None) -> str:
    """Stdout of a producer; a non-zero exit is a GateFault naming the producer and its first stderr line."""
    try:
        r = subprocess.run(cmd, cwd=str(repo), input=stdin, capture_output=True, text=True, timeout=120,
                           env={**os.environ, **(env or {})})
    except (OSError, subprocess.TimeoutExpired) as e:
        raise ProducerFault(f"producer {' '.join(cmd)} could not run: {e}") from None
    if r.returncode != 0:
        first = (r.stderr.strip().splitlines() or ["(no stderr)"])[0]
        raise ProducerFault(f"producer {' '.join(cmd)} exited {r.returncode}: {first}")
    return r.stdout


def _sample(glob: str) -> str:
    """A concrete path under a glob: `src/**` → `src/x/x.py`, `**/*.sql` → `x/x.sql`, `infra/` → `infra/x`."""
    g = glob.strip().strip("`")
    if g.endswith("/"):
        return g + "x"
    out = []
    for p in g.split("/"):
        if p == "**":
            out.append("x")
        elif "*" in p:
            out.append(p.replace("**", "x").replace("*", "x") if "." in p else "x")
        else:
            out.append(p)
    path = "/".join(out)
    return path if "." in Path(path).name else path + "/x.py"


def worst_case_path(cat: dict, rules: list[list[str]] | None = None) -> str:
    """The path that the most defect classes, families and path-bound rules govern — every one a line the pre-edit
    delivery carries (sample paths derived from their globs); the shortest such path. `rules`: each path-bound rule's
    `path_glob` list. Deterministic: candidates are sorted before the max."""
    rules = [r for r in (rules or []) if r]
    globs = [g for f in cat["families"] for g in f["surface"]] + [g for d in cat["dcs"] for g in d["paths"]] + [g for r in rules for g in r]
    candidates = {_sample(g) for g in globs if g != "*"}
    # a path can sit under several globs at once (src/** AND **/migrations/**): prepend literal directory
    # prefixes only — a wildcard prefix such as `**/migrations/` is not a directory to prepend
    prefixes = sorted({g[:-3] + "/" for g in globs if g.endswith("/**") and "*" not in g[:-3]})
    if not candidates:
        return "src/example.py"

    def score(p: str) -> int:
        return sum(1 for d in cat["dcs"] if d["paths"] == ["*"] or any_glob(p, d["paths"])) \
            + sum(1 for f in cat["families"] if any_glob(p, f["surface"])) + sum(1 for r in rules if any_glob(p, r))
    # a glob matches at any depth, so a prepended prefix never loses a match: keep a prefix only when it adds
    # one — one pass per candidate, never every combination of prefixes (2^prefixes candidates); then drop a
    # kept prefix that a later one made redundant (`contracts/` under `contracts/openapi/`)
    grown = set(candidates)
    for c in sorted(candidates):
        kept: list[str] = []
        for pre in prefixes:
            p = "".join(reversed(kept)) + c
            if not p.startswith(pre) and score(pre + p) > score(p):
                kept.append(pre)
        best = score("".join(reversed(kept)) + c)
        for pre in list(kept):
            rest = [k for k in kept if k != pre]
            if score("".join(reversed(rest)) + c) == best:
                kept = rest
        grown.add("".join(reversed(kept)) + c)
    return max(sorted(grown), key=lambda p: (score(p), -len(p)))   # equal scores: the shortest, then the sorted-first


def measure(repo: Path) -> dict:
    """Bytes emitted by each producer against its key. Every failure is a RED ROW (missing key, absent or
    dead producer, empty emission, overflow) — the caller exits 1. Only an unreadable config is a GateFault."""
    budgets = key(repo, "budgets", default={}) or {}
    cat = catalog(repo)
    rows: dict[str, dict] = {}

    def row(name: str, nbytes: int | None, producer: str, fault: str | None = None):
        cap = budgets.get(name)
        if type(cap) is not int:
            rows[name] = {"budget": None, "bytes": nbytes, "producer": producer, "ok": False, "fault": f"key budgets.{name} missing from config/quality.json"}
            return
        hook = budgets.get("hook_output_cap")
        if name in MUST_EMIT:   # a key above the harness cap is a budget the harness never honours (#240): named beside any producer fault
            over = None
            if type(hook) is not int:
                over = "key budgets.hook_output_cap missing from config/quality.json (the harness cap on one hook's text)"
            elif cap > hook:
                over = f"budgets.{name} = {cap} is over the harness hook cap budgets.hook_output_cap = {hook} — the harness would swap the text for a file path"
            if over:
                fault = f"{over}; {fault}" if fault else over
        ok = fault is None and (nbytes is None or (nbytes <= cap and (nbytes > 0 or name not in MUST_EMIT)))
        rows[name] = {"budget": cap, "bytes": nbytes, "producer": producer, "ok": ok, "fault": fault}

    def produce(name: str, path: Path, cmd: list[str], producer: str, stdin: str = "", env: dict | None = None):
        if not path.is_file():
            row(name, None, producer, fault=f"producer absent: {path.relative_to(repo)}")
            return
        try:
            row(name, len(_run(repo, cmd, stdin, env).encode()), producer)
        except ProducerFault as e:
            row(name, None, producer, fault=str(e))

    produce("session_start", repo / "scripts/validate-governance.sh", ["bash", "scripts/validate-governance.sh", "--banner"],
            "scripts/validate-governance.sh --banner")
    produce("prompt_submit", repo / "scripts/governance-onprompt.sh", ["bash", "scripts/governance-onprompt.sh"],
            "scripts/governance-onprompt.sh (worst case: snapshot reload + stale warning forced)",
            '{"session_id":"budget","prompt":"x"}', {"GOVERNANCE_ONPROMPT_WORST_CASE": "1"})
    pg = [r["applicable_when"].get("path_glob") for r in universe(repo)["rules"] if isinstance(r["applicable_when"], dict)]
    wpath = worst_case_path(cat, [[g for g in v if isinstance(g, str)] for v in pg if isinstance(v, list)])
    session = f"budget-{uuid.uuid4().hex}"   # a fresh session per run: the dedupe pointer must never be what is measured
    try:
        produce("pre_edit", repo / ".claude/hooks/deliver-governance.sh", ["bash", ".claude/hooks/deliver-governance.sh"],
                f".claude/hooks/deliver-governance.sh on {wpath}", json.dumps({"tool_input": {"file_path": wpath}, "session_id": session}))
    finally:
        marker = repo / ".claude/state" / f"governance-delivered-{session}.txt"
        if marker.is_file():
            marker.unlink()
    _notebook_rows(repo, budgets, produce)
    snap = repo / ".context/governance_snapshot.md"
    row("snapshot", snap.stat().st_size if snap.is_file() else None,
        ".context/governance_snapshot.md" + ("" if snap.is_file() else " (absent — n/a here)"))
    allv = laws(repo)
    row("law_sentence_max_chars", max((len(l["sentence"]) for l in allv["universal"] + allv["project"]), default=0),
        "longest law sentence in the index")
    row("dc_invariant_max_chars", max((len(d["invariant"]) for d in cat["dcs"]), default=0), "longest defect-class invariant")
    if "claude_md_advisory" in budgets:   # EVOL-064: advisory — over the key warns, never blocks; an absent key is no row
        # the framework repo measures the template it ships; a project its own file (a synced template tree is not its CLAUDE.md)
        cmd = repo / (".context/templates/setup/claude/CLAUDE.md" if context(repo) == "meta" else "CLAUDE.md")
        name = str(cmd.relative_to(repo))
        row("claude_md_advisory", cmd.stat().st_size if cmd.is_file() else None,
            f"{name} (re-read every turn; advisory)" if cmd.is_file() else f"{name} (absent — n/a here)")
        r = rows["claude_md_advisory"]
        if r["fault"] is None:
            r["ok"] = True
            r["warn"] = r["bytes"] is not None and r["bytes"] > r["budget"]
    nbytes, where = launch_context(repo)
    row("launch_context", nbytes, f"memory files loaded at launch ({where})")
    return rows


LAUNCH_ROOTS = ("CLAUDE.md", ".claude/CLAUDE.md", "CLAUDE.local.md")
IMPORT_HOPS = 5                                     # the harness follows @imports to five hops
_FENCE = re.compile(r"^\s*(```|~~~)")
_IMPORT = re.compile(r"(?<![\w`@])@((?:[\w.~-]+/)*[\w.-]+)")


def launch_context(repo: Path) -> tuple[int | None, str]:
    """EVOL-141: bytes of the memory files the harness loads at launch, and where they were read. A project reads its
    files on disk; the framework repo reads the templates at the paths they land on (the manifest's targets)."""
    root = repo.resolve()
    if context(repo) == "meta":
        from .discovery import inside, load_manifest
        tpl = ".context/templates/setup/"
        try:
            entries = load_manifest(repo).get("templates") or {}
        except GateFault as e:
            return None, f"n/a — {e}"
        files = {e["target"]: repo / (tpl + k) for k, e in entries.items()
                 if isinstance(e, dict) and inside(k) and inside(e.get("target"))}
        where = "the templates as they land"
    else:
        files, where = None, "the project's files"

    def raw(rel: str) -> bytes | None:
        p = files.get(rel) if files is not None else repo / rel
        try:
            return p.read_bytes() if p is not None and p.is_file() else None
        except OSError:
            return None

    def body(rel: str) -> str | None:
        b = raw(rel)
        return None if b is None else b.decode("utf-8", errors="replace")

    excludes: list[str] = []
    for s in (".claude/settings.json", ".claude/settings.local.json"):
        try:
            v = json.loads(body(s) or "{}").get("claudeMdExcludes")
        except (ValueError, AttributeError):
            v = None
        excludes += [x for x in v if isinstance(x, str)] if isinstance(v, list) else []

    def excluded(rel: str) -> bool:   # the harness matches every pattern against the absolute path: a relative one matches nothing
        a = (root / rel).as_posix()
        return any(re.fullmatch(_glob_regex(x), a) for x in excludes)

    seen: set[str] = set()
    total = 0

    def load(rel: str, hops: int) -> None:
        nonlocal total
        if rel in seen or excluded(rel):
            return
        b = raw(rel)
        if b is None:
            return
        seen.add(rel)
        total += len(b)
        text = b.decode("utf-8", errors="replace")
        if hops >= IMPORT_HOPS:
            return
        fenced = False
        for line in text.splitlines():
            if _FENCE.match(line):
                fenced = not fenced
                continue
            if fenced:
                continue
            for m in _IMPORT.finditer(re.sub(r"`[^`]*`", "", line)):
                t = (root / rel).parent / m.group(1)
                try:
                    t = t.resolve().relative_to(root).as_posix()
                except (ValueError, OSError, RuntimeError):
                    continue   # outside the project, a name too long, a symlink loop: never measured here
                load(t, hops + 1)

    for r in LAUNCH_ROOTS:
        load(r, 0)
    rules_loaded = 0
    rules = sorted(k for k in files if k.startswith(".claude/rules/") and k.endswith(".md")) if files is not None else \
        sorted(p.relative_to(repo).as_posix() for p in (repo / ".claude/rules").rglob("*.md") if p.is_file())
    for r in rules:
        text = body(r) or ""
        try:
            paths = frontmatter_of(text).get("paths")
        except Exception:   # invalid frontmatter: the harness loads the rule as if it had no paths
            paths = None
        if not paths and r not in seen and not excluded(r):
            rules_loaded += 1
            load(r, IMPORT_HOPS)
    if rules_loaded:   # a project list without the shipped entry (an upgrade keeps a present list whole): name the cure
        where += f"; {rules_loaded} rule bodies load at launch — claudeMdExcludes lacks \"**/.claude/rules/**\""
    return total, where


def _notebook_rows(repo: Path, budgets: dict, produce) -> None:
    """EVOL-133: both notebook producers on a throw-away session — a claimed notebook larger than the re-injection key
    and a transcript with every author after it. Every fixture is removed in `finally`."""
    sid = f"budget-{uuid.uuid4().hex}"
    nbd, std = repo / ".context/state/notebook", repo / ".claude/state"
    nb, state, marker = nbd / f"{sid}.md", std / f"notebook-{sid}.json", std / f"governance-reload-{sid}.marker"
    size = budgets.get("notebook_reinject") if type(budgets.get("notebook_reinject")) is int else 10000
    tdir = Path(tempfile.mkdtemp(prefix="nb-budget-"))
    try:
        nbd.mkdir(parents=True, exist_ok=True)
        std.mkdir(parents=True, exist_ok=True)
        entries = "".join(f"- 2026-01-01T00:00:{i % 60:02d}Z entry {i} " + "é" * 80 + "\n" for i in range(2 * size // 80 + 4))
        nb.write_text("## Standing\n" + "- decision in force " + "x" * 200 + "\n\n## Log\n" + entries, encoding="utf-8")
        os.utime(nb, (946684800, 946684800))
        now = datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.000Z")
        tr = tdir / "transcript.jsonl"
        lines = [{"type": "user", "timestamp": now, "message": {"content": "words"}},
                 {"type": "attachment", "timestamp": now, "attachment": {"type": "queued_command", "prompt": "q", "origin": {"kind": "human"}}},
                 {"type": "user", "isMeta": True, "timestamp": now, "message": {"content": "<cross-session-message from=\"p\">m"}},
                 {"type": "user", "timestamp": now, "message": {"content": ""}}] * 50
        tr.write_text("".join(json.dumps(x) + "\n" for x in lines), encoding="utf-8")
        state.write_text(json.dumps({"path": f".context/state/notebook/{sid}.md", "claimed_at": now, "reload": False,
                                     "unsaved": 0, "authors": []}), encoding="utf-8")
        produce("notebook_precompact", repo / "scripts/governance-oncompact.sh", ["bash", "scripts/governance-oncompact.sh"],
                "scripts/governance-oncompact.sh (claimed notebook, every author unsaved)",
                json.dumps({"hook_event_name": "PreCompact", "session_id": sid, "transcript_path": str(tr), "trigger": "auto"}))
        state.write_text(json.dumps({"path": f".context/state/notebook/{sid}.md", "claimed_at": now, "reload": True,
                                     "unsaved": 200, "authors": ["user", "queued", "peer", "other"], "lower_bound": True}), encoding="utf-8")
        produce("notebook_reinject", repo / "scripts/gates/notebook.py", ["python3", "scripts/gate.py", "notebook", "--hook-json"],
                "gate.py notebook --hook-json (UserPromptSubmit, reload pending, notebook over the key)",
                json.dumps({"hook_event_name": "UserPromptSubmit", "session_id": sid, "prompt": "x"}))
    finally:
        for f in (nb, state, marker):
            try:
                f.unlink()
            except OSError:
                pass
        shutil.rmtree(tdir, ignore_errors=True)


def summary(rows: dict) -> str:
    """The verdict line `gate.py budget` prints last: a passing run still names every advisory warning (EVOL-064)."""
    bad = [k for k, r in rows.items() if not r["ok"]]
    if bad:
        return f"budget: RED at {', '.join(bad)} — an overflow means shrink the producer or raise the key with its record; an empty emission means the producer is dead."
    warns = [f"WARN {k} {r['bytes']} > {r['budget']} (advisory, never blocks)" for k, r in rows.items() if r.get("warn")]
    return " · ".join(["budget: ok — every producer within its key."] + warns)


def render(rows: dict) -> str:
    out = ["| injection point | budget | measured | producer | |", "|---|---|---|---|---|"]
    for k, r in rows.items():
        state = ("WARN — over the advisory budget (never blocks)" if r.get("warn") else "ok") if r["ok"] else (f"RED — {r['fault']}" if r.get("fault") else ("EMPTY — dead producer" if r["bytes"] == 0 else "OVERFLOW"))
        out.append(f"| {k} | {r['budget'] if r['budget'] is not None else '—'} | {'n/a' if r['bytes'] is None else r['bytes']} | {r['producer']} | {state} |")
    return "\n".join(out)
